package org.kanger.storage.dumb2;
import java.nio.file.*;
import java.util.*;
import org.kanger.*;
import org.kanger.ContextProductionCapture.Source;
import org.kanger.ContextProductionNativeBinding.*;
import org.kanger.ContextUniversalFamilyInspection.Status;
import org.kanger.enums.StorageLifecycleErrorCode;
import org.kanger.exception.ContextProductionCommitException;

/** Solo and paired routes keep different minimal whole-source supports in either rule position. */
final class ContextDualMixedExistential {
    static int checks;static final int WORK=64000000;
    static void require(boolean value,String why){++checks;if(!value)throw new AssertionError(why);}
    static List<String> facts(int mode,String s){List<String> f=new ArrayList<>();if(mode==1||mode>=6)f.add("!"+s+"a(1);");if(mode==2||mode>=4)f.add("!"+s+"b(1);");if(mode==3||mode>=4)f.add("!"+s+"c("+(mode==5||mode==6?2:1)+");");return f;}
    static List<Set<String>> routes(int mode,boolean shared,String s){List<Set<String>> r=new ArrayList<>();if(mode==1||mode>=6)r.add(Collections.singleton("!"+s+"a(1);"));if(mode==4||mode==7||(!shared&&(mode==5||mode==6)))r.add(new HashSet<>(Arrays.asList("!"+s+"b(1);","!"+s+"c("+(mode==5||mode==6?2:1)+");")));return r;}
    static void verdict(ContextUniversalCandidate.Evaluation e,boolean candidateRule,String rule,String candidate,List<Set<String>> routes,String deny,int factCount){
        boolean safe=routes.isEmpty();require(e.status==(safe?Status.CONSISTENT:Status.COLLISION),"scope-sensitive solo/paired verdict: "+e.status+" / "+e.reason);
        if(safe){ContextUniversalFamilyModel.Certificate cert=e.qualification.certificate;require(cert!=null&&e.qualification.collision==null&&cert.cuts.size()==4,"all four cuts have complete consistent models");List<ContextUniversalUnitRounds.Receipt> receipts=new ArrayList<>();List<ContextUniversalQuotientModel.Model> models=new ArrayList<>();for(ContextUniversalFamilyModel.Cut c:cert.cuts){require(c.receipt.verified&&c.receipt.input==cert.input&&c.model.ledger==c.receipt.closureStep.input,"exact closure/model/common-frontier bindings");receipts.add(c.receipt);models.add(c.model);}require(ContextUniversalFamilyModel.certify(cert.input,receipts,models,16,65536,WORK).certified,"independent all-admissible-value model recertification");}
        else collision(e.qualification,e.artifact.foreign,e.artifact.staged,candidateRule,rule,candidate,routes,deny);
        List<Entry> entries=new ArrayList<>(e.artifact.staged.primary);for(Snapshot f:e.artifact.foreign)entries.addAll(f.primary);Entry whole=entries.stream().filter(v->v.statement.equals(rule)).findFirst().get();require(whole.kind==Kind.CLAUSES&&whole.witnesses()==0&&whole.clauses.size()==2&&whole.clauses.stream().anyMatch(c->c.literals.size()==2)&&whole.clauses.stream().anyMatch(c->c.literals.size()==3),"unequal solo/paired clauses retain their single whole Source");if(!candidateRule&&factCount>1)require(e.artifact.staged.primary.stream().filter(v->v.statement.equals(candidate)&&v.clauses.size()==factCount).count()==1,"conjoined candidate facts retain one whole Source");
    }
    static void collision(ContextUniversalFamilyInspection.Result r,List<Snapshot> foreign,Snapshot staged,boolean candidateRule,String rule,String candidate,List<Set<String>> routes,String deny){
        // A complete opposition stops local closure; later-depth logical routes are not enumerated.
        List<Set<String>> terminal=routes;
        if(candidateRule)for(Set<String> route:routes)if(route.size()==1){terminal=Collections.singletonList(route);break;}
        require(r.status==Status.COLLISION&&r.certificate==null&&r.collision!=null&&!r.collision.oppositions.isEmpty(),"complete solo/paired contradiction");Set<Source> expectedForeign=new HashSet<>();for(Snapshot f:foreign)for(Entry e:f.primary)if(e.statement.equals(deny)||(!candidateRule&&e.statement.equals(rule)))expectedForeign.add(e.source);require(expectedForeign.size()==(candidateRule?1:2),"exact whole private rule/Deny Sources");Set<Set<Source>> expected=new HashSet<>(),actual=new HashSet<>();if(staged!=null){Source proposed=staged.primary.stream().filter(e->e.statement.equals(candidate)).findFirst().get().source;if(candidateRule){for(Set<String> route:terminal){Set<Source> support=new HashSet<>();support.add(proposed);for(Entry e:staged.primary)if(route.contains(e.statement))support.add(e.source);require(support.size()==route.size()+1,"all required independent original facts exist");expected.add(support);}}else expected.add(Collections.singleton(proposed));}
        for(ContextUniversalUnitProof.Proof p:r.collision.oppositions){Set<Source> local=new HashSet<>(),other=new HashSet<>();for(Source s:p.support.sources)(s.localX?local:other).add(s);boolean allowed=!candidateRule&&local.size()==1;if(candidateRule)for(Set<String> route:terminal)if(local.size()==route.size()+1)allowed=true;require(p.dependsOnX&&p.contradiction&&p.conclusion==null&&allowed&&other.equals(expectedForeign)&&p.support.sources.size()==local.size()+expectedForeign.size(),"only necessary whole solo/paired Sources; no marker/extra route source");actual.add(local);if(staged!=null)require(expected.contains(local),"exact complete solo or paired support, no superset");}
        require(actual.size()==(candidateRule?terminal.size():1),"route count: actual="+actual.size()+" expected="+(candidateRule?terminal.size():1)+" barriers="+r.completedBarriers+" proofCount="+r.collision.oppositions.size()+"; whole conjunction is not split");if(staged!=null)require(actual.equals(expected),"all and only expected whole-source routes retained");
    }
    static void one(boolean negative,boolean reverse,boolean nativePath,boolean shared,int mode,boolean candidateRule)throws Exception{
        Path dir=Files.createTempDirectory("dual-mixed-existential-write-");System.setProperty("user.home",dir.toString());String s=negative?"~":"",op=negative?"":"~",deny="!"+op+"q();",rule=shared?"!($x ("+s+"a(x)||("+s+"b(x)&&"+s+"c(x))))->"+s+"q();":"!(($x "+s+"a(x))||(($y "+s+"b(y))&&($z "+s+"c(z))))->"+s+"q();";List<String> facts=facts(mode,s);List<Set<String>> routes=routes(mode,shared,s);boolean safe=routes.isEmpty();String candidate=rule;if(!candidateRule){candidate="!safe(1);";if(!facts.isEmpty()){List<String> terms=new ArrayList<>();for(String f:facts)terms.add(f.substring(1,f.length()-1));candidate="!"+String.join("&&",terms)+";";}}final String proposed=candidate;
        ContextSevenPremiseNativeWriteRunner.create(dir,"Bridge",candidateRule?"!bridgeMarker(2);":rule);ContextSevenPremiseNativeWriteRunner.create(dir,"Deny",deny);ContextSevenPremiseNativeWriteRunner.create(dir,"Other","!other(2);");Set<String> settled;List<RevisionRef> pins;long afterRevision;
        try(ContextSevenPremiseNativeWriteRunner.Fixture f=new ContextSevenPremiseNativeWriteRunner.Fixture(dir,"X")){
            String base="!base(2);";if(candidateRule)for(String fact:facts)base+=" "+fact;require(f.root.compile(base,null,false),"only selected original route facts");for(String name:reverse?new String[]{"Other","Deny","Bridge"}:new String[]{"Bridge","Deny","Other"})f.db.connectContext(name);f.db.saveConnections(f.root);
            ContextProductionInventory before=ContextSevenPremiseNativeWriteRunner.inventory(f);Set<String> origins=ContextSevenPremiseNativeWriteRunner.origins(before);long revision=f.db.getRevision();int rules=f.root.getRules().size();pins=ContextSevenPremiseNativeWriteRunner.pins(f);List<String> foreignPrints;
            try(ContextProductionSnapshotSession lease=ContextProductionSnapshotSession.open(f.db,f.root,1000)){foreignPrints=ContextForeignAntecedentQuantifier.fingerprints(lease.inventory());ContextProductionSnapshotSession.Binding bound=lease.bind(WORK,500000);require(bound.foreign.size()==3,"all private cuts bind");if(!candidateRule)require(bound.foreign.stream().flatMap(v->v.primary.stream()).filter(v->v.statement.equals(rule)&&v.clauses.size()==2).count()==1,"one whole private rule with unequal route clauses");}
            ContextUniversalCandidate.Evaluation diagnostic=f.db.qualifyUniversalProductionCandidate(f.root,proposed,1000,16,16,16,65536,1000000,WORK,500000,WORK);verdict(diagnostic,candidateRule,rule,proposed,routes,deny,facts.size());require(f.db.getRevision()==revision&&ContextSevenPremiseNativeWriteRunner.inventory(f).fingerprint.equals(before.fingerprint),"diagnostic preserves physical source");
            if(nativePath){ContextPendingNativeWrite attempt=f.db.beginUniversalWrite(f.root,1000,16,16,16,65536,1000000,WORK,500000,WORK,WORK);try{ContextProductionCommitException failure=null;try{f.root.query(proposed,null,false);}catch(ContextProductionCommitException caught){failure=caught;}if(safe)require(failure==null,"actual native safe solo/paired publication");else{require(failure!=null&&failure.getErrorCode()==StorageLifecycleErrorCode.STORAGE_CONTEXT_CONFLICT&&failure.getFamilyAudit()!=null&&failure.getFamilyAudit().verified&&failure.getFamilyAudit().verdict!=diagnostic.qualification,"actual native conflict freshly audited");collision(failure.getFamilyAudit().verdict,diagnostic.artifact.foreign,null,candidateRule,rule,proposed,routes,deny);}}finally{f.db.endNativeWrite(attempt);}}
            else{DB.UniversalProductionWriteResult result=f.db.writeUniversalProductionCandidate(f.root,proposed,1000,16,16,16,65536,1000000,WORK,500000,WORK,WORK,false);require(result.status==(safe?DB.ProductionWriteStatus.PUBLISHED:DB.ProductionWriteStatus.COLLISION)&&result.trial!=diagnostic&&result.audit!=null&&result.audit.verified&&result.audit.evaluation==result.trial,"fresh exact public trial/audit governs route verdict");verdict(result.trial,candidateRule,rule,proposed,routes,deny,facts.size());require(result.before.getRevision()==revision&&result.after.getRevision()==f.db.getRevision(),"actual public physical references");}
            ContextProductionInventory after=ContextSevenPremiseNativeWriteRunner.inventory(f);settled=ContextSevenPremiseNativeWriteRunner.origins(after);afterRevision=f.db.getRevision();Set<String> expected=new HashSet<>(origins);if(safe)expected.add(proposed);require(settled.equals(expected)&&after.primary.size()==expected.size()&&ContextSevenPremiseNativeWriteRunner.pins(f).equals(pins),"only whole proposed Source publishes; no foreign/derived primary imports");if(safe)require(afterRevision>revision,"safe publication advances revision");else require(afterRevision==revision&&f.root.getRules().size()==rules&&after.fingerprint.equals(before.fingerprint),"refusal preserves exact revision/rules/fingerprint");try(ContextProductionSnapshotSession lease=ContextProductionSnapshotSession.open(f.db,f.root,1000)){require(ContextForeignAntecedentQuantifier.fingerprints(lease.inventory()).equals(foreignPrints),"all private initialized fingerprints unchanged");}
        }
        try(ContextSevenPremiseNativeWriteRunner.Fixture f=new ContextSevenPremiseNativeWriteRunner.Fixture(dir,"X")){require(f.db.getRevision()>=afterRevision&&ContextSevenPremiseNativeWriteRunner.origins(ContextSevenPremiseNativeWriteRunner.inventory(f)).equals(settled)&&ContextSevenPremiseNativeWriteRunner.pins(f).equals(pins),"ordinary durable reopen retains exact whole settled origins/pins");try(ContextProductionSnapshotSession lease=ContextProductionSnapshotSession.open(f.db,f.root,1000)){require(lease.bind(WORK,500000).foreign.size()==3,"all private cuts bind after durable reopen");}}
    }
    static void run(boolean negative,boolean proof,String marker){try{for(boolean r:new boolean[]{false,true})for(boolean p:new boolean[]{false,true})for(boolean s:new boolean[]{false,true})for(int m=proof?4:0;m<(proof?8:4);m++)for(boolean c:new boolean[]{false,true})try{one(negative,r,p,s,m,c);}catch(Throwable failure){System.out.println("CASE negative="+negative+" reverse="+r+" native="+p+" shared="+s+" mode="+m+" candidateRule="+c);throw failure;}System.out.println(marker+" checks="+(checks+ContextSevenPremiseNativeWriteRunner.checks));System.exit(0);}catch(Throwable e){e.printStackTrace();System.exit(1);}}
}
